import { useEffect, useRef } from 'react'
import { useCanvasStore } from '@/store/useCanvasStore'
import { useUIStore } from '@/store/useUIStore'
import { NODE_COLORS, BORDER_COLORS } from '@/constants'

interface NodeContextMenuProps {
  nodeId: string
  position: { x: number; y: number }
  onClose: () => void
}

export function NodeContextMenu({ nodeId, position, onClose }: NodeContextMenuProps) {
  const { nodes, updateNode, removeNode, duplicateNode } = useCanvasStore()
  const { openStylePanel, setSelectedNodeIds } = useUIStore()

  const menuRef = useRef<HTMLDivElement>(null)
  const node = nodes.get(nodeId)

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
        onClose()
      }
    }

    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onClose()
      }
    }

    document.addEventListener('mousedown', handleClickOutside)
    document.addEventListener('keydown', handleEscape)

    return () => {
      document.removeEventListener('mousedown', handleClickOutside)
      document.removeEventListener('keydown', handleEscape)
    }
  }, [onClose])

  if (!node) return null

  const handleEdit = () => {
    const { setEditingId } = useCanvasStore.getState()
    setEditingId(nodeId)
    onClose()
  }

  const handleDuplicate = () => {
    duplicateNode(nodeId)
    onClose()
  }

  const handleDelete = () => {
    removeNode(nodeId)
    onClose()
  }

  const handleLock = () => {
    updateNode(nodeId, { locked: !node.locked })
    onClose()
  }

  const handleBringToFront = () => {
    // Move node to end of map (renders on top)
    const { nodes: allNodes } = useCanvasStore.getState()
    const newNodes = new Map(allNodes)
    const currentNode = newNodes.get(nodeId)
    if (currentNode) {
      newNodes.delete(nodeId)
      newNodes.set(nodeId, currentNode)
      useCanvasStore.setState({ nodes: newNodes })
    }
    onClose()
  }

  const handleSendToBack = () => {
    // Move node to start of map (renders at bottom)
    const { nodes: allNodes } = useCanvasStore.getState()
    const newNodes = new Map(allNodes)
    const currentNode = newNodes.get(nodeId)
    if (currentNode) {
      newNodes.delete(nodeId)
      const orderedNodes = new Map([[nodeId, currentNode], ...Array.from(newNodes.entries())])
      useCanvasStore.setState({ nodes: orderedNodes })
    }
    onClose()
  }

  const handleColorChange = (color: string) => {
    updateNode(nodeId, { color })
    onClose()
  }

  const handleEditStyle = () => {
    setSelectedNodeIds([nodeId])
    openStylePanel()
    onClose()
  }

  const menuItems = [
    {
      label: '编辑',
      icon: '✏️',
      action: handleEdit,
      shortcut: 'Enter',
      disabled: node.locked,
    },
    { label: '复制', icon: '📋', action: handleDuplicate, shortcut: 'Ctrl+D' },
    { label: '删除', icon: '🗑️', action: handleDelete, shortcut: 'Del', divider: true },
    { label: node.locked ? '解锁' : '锁定', icon: node.locked ? '🔓' : '🔒', action: handleLock },
    {
      label: '置于顶层',
      icon: '⬆️',
      action: handleBringToFront,
    },
    {
      label: '置于底层',
      icon: '⬇️',
      action: handleSendToBack,
      divider: true,
    },
    {
      label: '编辑样式...',
      icon: '🎨',
      action: handleEditStyle,
    },
  ]

  return (
    <>
      {/* Backdrop */}
      <div className="fixed inset-0 z-40" onClick={onClose} />

      {/* Menu */}
      <div
        ref={menuRef}
        className="fixed z-50 min-w-[200px] bg-white dark:bg-gray-800 rounded-lg shadow-xl border border-gray-200 dark:border-gray-700 py-1"
        style={{
          left: position.x,
          top: position.y,
        }}
      >
        {menuItems.map((item, index) => (
          <div key={index}>
            {item.divider && <div className="border-t border-gray-200 dark:border-gray-700 my-1" />}
            <button
              className="w-full px-4 py-2 text-left hover:bg-gray-100 dark:hover:bg-gray-700 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-between"
              onClick={item.action}
              disabled={item.disabled}
            >
              <span className="flex items-center gap-2">
                <span>{item.icon}</span>
                <span className="text-sm text-gray-700 dark:text-gray-300">{item.label}</span>
              </span>
              {item.shortcut && (
                <span className="text-xs text-gray-500 dark:text-gray-400">{item.shortcut}</span>
              )}
            </button>
          </div>
        ))}

        {/* Color picker submenu */}
        <div className="border-t border-gray-200 dark:border-gray-700 my-1">
          <div className="px-4 py-2 text-xs text-gray-500 dark:text-gray-400 font-medium">
            背景颜色
          </div>
          <div className="grid grid-cols-6 gap-1 px-2 pb-2">
            {NODE_COLORS.map((color) => (
              <button
                key={color}
                className="w-6 h-6 rounded border border-gray-300 dark:border-gray-600 hover:scale-110 transition-transform"
                style={{ backgroundColor: color }}
                onClick={() => handleColorChange(color)}
                title={color}
              />
            ))}
          </div>
        </div>
      </div>
    </>
  )
}
