import { useEffect, useState, useRef, useCallback } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { useCanvasStore } from '@/store/useCanvasStore'
import { useProjectsStore } from '@/store/useProjectsStore'
import { useAuthStore } from '@/store/useAuthStore'
import { useUIStore } from '@/store/useUIStore'
import { CanvasToolbar } from '@/components/canvas/CanvasToolbar'
import { CanvasGrid } from '@/components/canvas/CanvasGrid'
import { CanvasMinimap } from '@/components/canvas/CanvasMinimap'
import { ZoomControls } from '@/components/canvas/ZoomControls'
import { NodeItem } from '@/components/canvas/NodeItem'
import { NodeStylePanel } from '@/components/canvas/NodeStylePanel'
import { generateId } from '@/utils/canvas'
import { saveToCache, loadFromCache } from '@/utils/nodeCache'
import { saveCanvasNodesData, loadCanvasNodesData } from '@/services/api'
import type { Node } from '@/types'

// Simple logger that writes to a file-accessible location
const debugLog = (...args: any[]) => {
  const timestamp = new Date().toISOString()
  const logEntry = `[${timestamp}] ${args.map(a => typeof a === 'object' ? JSON.stringify(a) : a).join(' ')}\n`
  // Store in sessionStorage for easy access
  const existingLogs = sessionStorage.getItem('debug_logs') || ''
  sessionStorage.setItem('debug_logs', existingLogs + logEntry)
  // Also log to console for visibility
  console.log(...args)
}

const AUTO_SAVE_INTERVAL = 5000 // 5 seconds
const CACHE_SAVE_DELAY = 500 // 500ms debounce for localStorage

export function CanvasPage() {
  const { canvasId } = useParams<{ canvasId: string }>()
  const navigate = useNavigate()
  const containerRef = useRef<HTMLDivElement>(null)
  const [isDragging, setIsDragging] = useState(false)
  const [isSpacePressed, setIsSpacePressed] = useState(false)
  const [containerSize, setContainerSize] = useState({ width: 1000, height: 800 })
  const [lastSaveTime, setLastSaveTime] = useState<number>(0)
  const dragStartRef = useRef({ x: 0, y: 0 })
  const panStartRef = useRef({ x: 0, y: 0 })
  const cacheTimeoutRef = useRef<ReturnType<typeof setTimeout>>()
  const dbSaveTimeoutRef = useRef<ReturnType<typeof setTimeout>>()
  const mouseDownOnContentRef = useRef(false) // Track if mouse down was on content

  const { user } = useAuthStore()
  const {
    nodes,
    groups,
    domains,
    connections,
    zoom,
    panX,
    panY,
    selectedIds,
    isDirty,
    setCanvasId,
    setCanvasData,
    setZoom,
    setPan,
    setEditingId,
    setSelectedIds,
    clearCanvas,
    addNode,
    addDomain,
    setDirty,
  } = useCanvasStore()

  const {
    currentTool,
    dragMode,
    nodePoolOpen,
    stylePanelOpen,
    setCurrentTool,
    toggleGrid,
  } = useUIStore()

  const { loadProjects, restoreCurrentProject, canvases } = useProjectsStore()

  // 恢复项目状态
  useEffect(() => {
    const initProject = async () => {
      await loadProjects()
      await restoreCurrentProject()
    }
    initProject()
  }, [loadProjects, restoreCurrentProject])

  // 检查当前画布是否已被删除
  useEffect(() => {
    if (!canvasId) return

    const id = parseInt(canvasId)
    if (isNaN(id)) return

    // 检查当前画布是否还在画布列表中
    const canvasExists = canvases.some(c => c.id === id)

    // 如果画布已被删除，重定向到项目列表
    if (!canvasExists && canvases.length >= 0) {
      // 清空画布状态
      clearCanvas()
      setCanvasId(null)
      // 重定向到项目列表
      navigate('/projects', { replace: true })
    }
  }, [canvasId, canvases, clearCanvas, setCanvasId, navigate])

  // Load canvas data on mount
  useEffect(() => {
    if (!canvasId) return

    const id = parseInt(canvasId)
    if (isNaN(id)) return

    setCanvasId(id)

    // Step 1: Load from localStorage cache first (fast)
    const cachedData = loadFromCache(id)
    if (cachedData) {
      setCanvasData(cachedData)
    }

    // Step 2: Load from database (authoritative source)
    const loadFromDatabase = async () => {
      try {
        const dbData = await loadCanvasNodesData(id)

        if (dbData && (dbData.nodes.length > 0 || dbData.groups.length > 0 ||
                        dbData.domains.length > 0 || dbData.connections.length > 0)) {
          setCanvasData(dbData)
          // Update cache with latest database data
          saveToCache(id, dbData)
        } else if (!cachedData) {
          // No data in cache or database, start fresh
        }
      } catch (error) {
        console.error('[Canvas] Failed to load from database:', error)
      }
    }

    loadFromDatabase()

    return () => {
      clearTimeout(cacheTimeoutRef.current)
      clearTimeout(dbSaveTimeoutRef.current)
    }
  }, [canvasId, setCanvasId, setCanvasData])

  // Auto-save to localStorage (debounced)
  useEffect(() => {
    if (!canvasId || !isDirty) return

    const id = parseInt(canvasId)

    // Clear previous timeout
    if (cacheTimeoutRef.current) {
      clearTimeout(cacheTimeoutRef.current)
    }

    // Debounced save to localStorage
    cacheTimeoutRef.current = setTimeout(() => {
      const nodesArray = Array.from(nodes.values())
      const groupsArray = Array.from(groups.values())
      const domainsArray = Array.from(domains.values())
      const connectionsArray = Array.from(connections.values())

      saveToCache(id, {
        nodes: nodesArray,
        groups: groupsArray,
        domains: domainsArray,
        connections: connectionsArray,
      })
    }, CACHE_SAVE_DELAY)
  }, [canvasId, isDirty, nodes, groups, domains, connections])

  // Periodic save to database
  useEffect(() => {
    if (!canvasId) return

    const id = parseInt(canvasId)

    const saveToDatabase = async () => {
      // Skip if no changes
      if (!isDirty) {
        // Reschedule
        dbSaveTimeoutRef.current = setTimeout(saveToDatabase, AUTO_SAVE_INTERVAL)
        return
      }

      // Skip if recently saved (avoid excessive saves)
      const now = Date.now()
      if (now - lastSaveTime < AUTO_SAVE_INTERVAL) {
        dbSaveTimeoutRef.current = setTimeout(saveToDatabase, AUTO_SAVE_INTERVAL)
        return
      }

      try {
        const nodesArray = Array.from(nodes.values())
        const groupsArray = Array.from(groups.values())
        const domainsArray = Array.from(domains.values())
        const connectionsArray = Array.from(connections.values())

        await saveCanvasNodesData(id, {
          nodes: nodesArray,
          groups: groupsArray,
          domains: domainsArray,
          connections: connectionsArray,
        })

        setLastSaveTime(now)
        setDirty(false)
      } catch (error) {
        console.error('[Auto-save] Failed to save to database:', error)
      }

      // Schedule next save
      dbSaveTimeoutRef.current = setTimeout(saveToDatabase, AUTO_SAVE_INTERVAL)
    }

    // Start the save loop
    dbSaveTimeoutRef.current = setTimeout(saveToDatabase, AUTO_SAVE_INTERVAL)

    return () => {
      if (dbSaveTimeoutRef.current) {
        clearTimeout(dbSaveTimeoutRef.current)
      }
    }
  }, [canvasId, isDirty, nodes, groups, domains, connections, lastSaveTime, setDirty])

  // Handle space key for panning
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'Space' && !e.repeat) {
        setIsSpacePressed(true)
      }
    }

    const handleKeyUp = (e: KeyboardEvent) => {
      if (e.code === 'Space') {
        setIsSpacePressed(false)
        setIsDragging(false)
      }
    }

    window.addEventListener('keydown', handleKeyDown)
    window.addEventListener('keyup', handleKeyUp)

    return () => {
      window.removeEventListener('keydown', handleKeyDown)
      window.removeEventListener('keyup', handleKeyUp)
    }
  }, [])

  // Update container size
  useEffect(() => {
    const updateSize = () => {
      if (containerRef.current) {
        setContainerSize({
          width: containerRef.current.clientWidth,
          height: containerRef.current.clientHeight,
        })
      }
    }

    updateSize()
    window.addEventListener('resize', updateSize)

    const resizeObserver = new ResizeObserver(updateSize)
    if (containerRef.current) {
      resizeObserver.observe(containerRef.current)
    }

    return () => {
      window.removeEventListener('resize', updateSize)
      resizeObserver.disconnect()
    }
  }, [])

  // Handle keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Don't handle shortcuts when typing in input fields
      if (
        e.target instanceof HTMLInputElement ||
        e.target instanceof HTMLTextAreaElement
      ) {
        return
      }

      // Tool shortcuts
      if (e.key === 'v' || e.key === 'V') {
        setCurrentTool('select')
      } else if (e.key === 'h' || e.key === 'H') {
        setCurrentTool('pan')
      } else if (e.key === 'n' || e.key === 'N') {
        setCurrentTool('node')
      } else if (e.key === 'r' || e.key === 'R') {
        setCurrentTool('domain')
      } else if (e.key === 'l' || e.key === 'L') {
        setCurrentTool('connection')
      } else if (e.key === 'g' || e.key === 'G') {
        if (e.ctrlKey || e.metaKey) {
          // Ctrl+G: Create group
        } else {
          toggleGrid()
        }
      } else if (e.key === 'Escape') {
        setCurrentTool('select')
        setEditingId(null)
      }

      // Zoom shortcuts
      if ((e.ctrlKey || e.metaKey) && e.key === '0') {
        e.preventDefault()
        setZoom(1)
        setPan(0, 0)
      } else if ((e.ctrlKey || e.metaKey) && (e.key === '=' || e.key === '+')) {
        e.preventDefault()
        setZoom(Math.min(zoom + 0.1, 5))
      } else if ((e.ctrlKey || e.metaKey) && e.key === '-') {
        e.preventDefault()
        setZoom(Math.max(zoom - 0.1, 0.1))
      }
    }

    window.addEventListener('keydown', handleKeyDown)

    return () => {
      window.removeEventListener('keydown', handleKeyDown)
    }
  }, [zoom, setCurrentTool, setZoom, setPan, toggleGrid, setEditingId])

  // Handle mouse down for drag panning
  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    // Reset the flag on each mouse down
    mouseDownOnContentRef.current = false

    // Trigger on: middle mouse, space + left mouse, or when pan tool is active
    if (e.button === 1 || (e.button === 0 && (isSpacePressed || currentTool === 'pan'))) {
      e.preventDefault()
      setIsDragging(true)
      dragStartRef.current = { x: e.clientX, y: e.clientY }
      panStartRef.current = { x: panX, y: panY }
    }
  }, [isSpacePressed, currentTool, panX, panY])

  // Handle mouse move for drag panning
  const handleMouseMove = useCallback((e: React.MouseEvent) => {
    if (!isDragging) return

    const dx = e.clientX - dragStartRef.current.x
    const dy = e.clientY - dragStartRef.current.y

    setPan(panStartRef.current.x + dx, panStartRef.current.y + dy)
  }, [isDragging, setPan])

  // Handle mouse up
  const handleMouseUp = useCallback(() => {
    setIsDragging(false)
  }, [])

  // Handle mouse wheel for zooming and panning
  const handleWheel = (e: React.WheelEvent) => {
    if (e.shiftKey) {
      // Horizontal pan
      e.preventDefault()
      setPan(panX - e.deltaY, panY)
    } else if (e.ctrlKey || e.metaKey) {
      // Vertical pan (when Ctrl/Meta is pressed)
      e.preventDefault()
      setPan(panX, panY - e.deltaY)
    } else {
      // Zoom (default behavior)
      e.preventDefault()
      const delta = e.deltaY * -0.001
      const newZoom = Math.min(Math.max(zoom + delta, 0.1), 5)
      setZoom(newZoom)
    }
  }

  // Handle canvas click
  const handleCanvasClick = (e: React.MouseEvent) => {
    // Don't handle click when using pan tool or just finished dragging
    if (currentTool === 'pan' || isDragging) return

    // Clear selection when clicking on empty canvas
    if (currentTool === 'select') {
      setSelectedIds([])
      return
    }

    // Prevent double-firing
    if (e.detail > 1) return

    // Check if clicking on an existing node
    const target = e.target as HTMLElement
    const clickedOnNode = target.closest('.node-item')
    if (clickedOnNode) {
      debugLog('[Click on Node] Blocked - clicked on existing node')
      return
    }

    // Check if clicking on other interactive elements
    if (target.closest('button') || target.closest('canvas') || target.closest('[role="button"]')) {
      debugLog('[Click on Interactive] Blocked')
      return
    }

    const rect = e.currentTarget.getBoundingClientRect()
    // Get the click position relative to the container
    const clickX = e.clientX - rect.left
    const clickY = e.clientY - rect.top

    // The canvas content uses transform: translate(panX, panY) scale(zoom) with transform-origin: 0 0
    // CSS transform execution: first scale, then translate (translate is NOT affected by scale)
    // For a point (canvasX, canvasY):
    //   screenX = canvasX * zoom + panX
    //   screenY = canvasY * zoom + panY
    // Reverse: canvasX = (screenX - panX) / zoom
    const x = (clickX - panX) / zoom
    const y = (clickY - panY) / zoom

    debugLog('[Node Creation]', {
      clickScreenPos: { x: Math.round(clickX), y: Math.round(clickY) },
      transform: { panX: Math.round(panX), panY: Math.round(panY), zoom: zoom.toFixed(2) },
      calculatedCanvasPos: { x: Math.round(x), y: Math.round(y) },
      target: target.tagName,
      allNodesCount: nodes.size
    })

    const snappedX = dragMode === 'grid' ? Math.round(x / 20) * 20 : x
    const snappedY = dragMode === 'grid' ? Math.round(y / 20) * 20 : y

    if (currentTool === 'node') {
      const newNode = {
        id: generateId('node'),
        x: snappedX,
        y: snappedY,
        width: 200,
        height: 120,
        title: '新节点',
        content: '',
        color: '#ffffff',
        borderColor: '#e5e7eb',
        borderWidth: 1,
        borderRadius: 8,
        fontSize: 14,
        textAlign: 'center' as const,
        collapsed: false,
        locked: false,
      }

      debugLog('[Before addNode]', {
        nodeId: newNode.id,
        newNodePos: { x: Math.round(newNode.x), y: Math.round(newNode.y) },
        currentPan: { panX: Math.round(panX), panY: Math.round(panY) },
        currentZoom: zoom.toFixed(2)
      })

      addNode(newNode)

      // Verify the node was stored correctly using the fresh state
      requestAnimationFrame(() => {
        const freshNodes = useCanvasStore.getState().nodes
        const storedNode = freshNodes.get(newNode.id)
        debugLog('[After addNode]', {
          nodeId: newNode.id,
          stored: !!storedNode,
          storedNodePos: storedNode ? { x: Math.round(storedNode.x), y: Math.round(storedNode.y) } : null,
          totalNodes: freshNodes.size
        })
      })

      setCurrentTool('select')
    } else if (currentTool === 'domain') {
      const newDomain = {
        id: generateId('domain'),
        name: '新建域',
        x: snappedX,
        y: snappedY,
        width: 400,
        height: 300,
        backgroundColor: 'rgba(156, 163, 175, 0.1)',
        borderColor: '#9ca3af',
        borderWidth: 2,
        titleVisible: true,
      }

      addDomain(newDomain)
      setCurrentTool('select')
    }
  }

  // Handle keyboard shortcuts for node operations
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Don't handle shortcuts when typing in input fields
      if (
        e.target instanceof HTMLInputElement ||
        e.target instanceof HTMLTextAreaElement ||
        (e.target as HTMLElement).contentEditable === 'true'
      ) {
        return
      }

      // Delete selected nodes
      if ((e.key === 'Delete' || e.key === 'Backspace') && selectedIds.length > 0) {
        const { removeNode } = useCanvasStore.getState()
        selectedIds.forEach((id) => removeNode(id))
        setSelectedIds([])
      }

      // Duplicate selected nodes
      if ((e.key === 'd' || e.key === 'D') && (e.ctrlKey || e.metaKey)) {
        e.preventDefault()
        const { duplicateNode } = useCanvasStore.getState()
        if (selectedIds.length === 1) {
          duplicateNode(selectedIds[0])
        }
      }

      // Copy nodes (for future paste functionality)
      if ((e.key === 'c' || e.key === 'C') && (e.ctrlKey || e.metaKey)) {
        // Store selected nodes in clipboard
        const nodesToCopy = selectedIds.map((id) => nodes.get(id)).filter(Boolean)
        sessionStorage.setItem('clipboard_nodes', JSON.stringify(nodesToCopy))
      }

      // Paste nodes
      if ((e.key === 'v' || e.key === 'V') && (e.ctrlKey || e.metaKey)) {
        const clipboard = sessionStorage.getItem('clipboard_nodes')
        if (clipboard) {
          try {
            const nodesToPaste = JSON.parse(clipboard) as Node[]
            nodesToPaste.forEach((node) => {
              const newNode = {
                ...node,
                id: generateId('node'),
                x: node.x + 20,
                y: node.y + 20,
              }
              addNode(newNode)
            })
          } catch (e) {
            console.error('Failed to paste nodes:', e)
          }
        }
      }

      // Select all nodes
      if ((e.key === 'a' || e.key === 'A') && (e.ctrlKey || e.metaKey)) {
        e.preventDefault()
        setSelectedIds(Array.from(nodes.keys()))
      }
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [selectedIds, nodes, addNode, setSelectedIds])

  // 验证画布ID有效性
  const validCanvasId = canvasId ? parseInt(canvasId) : null
  const isCanvasValid = validCanvasId !== null && !isNaN(validCanvasId)

  // 如果没有有效的画布ID，显示提示界面
  if (!isCanvasValid) {
    return (
      <div className="h-full flex items-center justify-center bg-gray-100 dark:bg-gray-900">
        <div className="text-center p-8 bg-white dark:bg-gray-800 rounded-lg shadow-lg">
          <div className="mb-4">
            <svg
              className="mx-auto h-16 w-16 text-gray-400"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M9 13h6m-3-3v6m-9 1V7a2 2 0 012-2h6l2 2h6a2 2 0 012 2v8a2 2 0 01-2 2H5a2 2 0 01-2-2z"
              />
            </svg>
          </div>
          <h2 className="text-xl font-semibold text-gray-800 dark:text-gray-200 mb-2">
            请先选择一个画布
          </h2>
          <p className="text-gray-600 dark:text-gray-400 mb-6">
            您需要从左侧项目栏中选择一个画布才能开始编辑
          </p>
          <div className="flex justify-center gap-4">
            <button
              onClick={() => window.location.href = '/projects'}
              className="px-6 py-2 bg-blue-500 hover:bg-blue-600 text-white rounded-lg transition-colors"
            >
              前往项目列表
            </button>
            <button
              onClick={() => window.history.back()}
              className="px-6 py-2 bg-gray-300 hover:bg-gray-400 dark:bg-gray-700 dark:hover:bg-gray-600 text-gray-800 dark:text-gray-200 rounded-lg transition-colors"
            >
              返回上一页
            </button>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="h-full flex flex-col bg-gray-100 dark:bg-gray-900">
      {/* Canvas Toolbar */}
      <div className="flex items-center justify-between px-4 py-2 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800">
        <CanvasToolbar />

        {/* Debug: Download logs button */}
        <button
          onClick={() => {
            const logs = sessionStorage.getItem('debug_logs') || 'No logs yet'
            const blob = new Blob([logs], { type: 'text/plain' })
            const url = URL.createObjectURL(blob)
            const a = document.createElement('a')
            a.href = url
            a.download = `mindmap-debug-${Date.now()}.txt`
            a.click()
            URL.revokeObjectURL(url)
          }}
          className="px-3 py-1 text-xs bg-gray-200 dark:bg-gray-700 hover:bg-gray-300 dark:hover:bg-gray-600 rounded"
          title="下载调试日志"
        >
          📥 下载日志
        </button>
      </div>

      {/* Canvas Container */}
      <div
        ref={containerRef}
        className="flex-1 relative overflow-hidden"
        onWheel={handleWheel}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        onClick={handleCanvasClick}
        style={{
          cursor: isDragging ? 'grabbing' : currentTool === 'pan' || isSpacePressed ? 'grab' : currentTool === 'node' ? 'crosshair' : currentTool === 'domain' ? 'cell' : 'default',
          userSelect: isDragging || currentTool === 'pan' ? 'none' : undefined,
        }}
      >
        {/* Grid */}
        <CanvasGrid zoom={zoom} panX={panX} panY={panY} />

        {/* Minimap */}
        <CanvasMinimap
          nodes={nodes}
          groups={groups}
          domains={domains}
          zoom={zoom}
          panX={panX}
          panY={panY}
          containerWidth={containerSize.width}
          containerHeight={containerSize.height}
          nodePoolOpen={nodePoolOpen}
          onViewportChange={setPan}
        />

        {/* Canvas content */}
        <div
          className="absolute"
          style={{
            transform: `translate(${panX}px, ${panY}px) scale(${zoom})`,
            transformOrigin: '0 0',
            // Don't set width/height on the transformed container
            // Let it size to content
          }}
          onMouseDown={() => {
            mouseDownOnContentRef.current = true
          }}
        >
          {/* Render domains */}
          {Array.from(domains.values()).map((domain) => (
            <div
              key={domain.id}
              className="absolute border"
              style={{
                left: domain.x,
                top: domain.y,
                width: domain.width,
                height: domain.height,
                backgroundColor: domain.backgroundColor,
                borderColor: domain.borderColor,
                borderWidth: domain.borderWidth,
              }}
            >
              {domain.titleVisible && domain.name && (
                <div className="absolute -top-6 left-0 px-2 py-1 bg-gray-200 dark:bg-gray-700 rounded text-xs font-medium">
                  {domain.name}
                </div>
              )}
            </div>
          ))}

          {/* Render connections */}
          <svg className="absolute inset-0 pointer-events-none" style={{ overflow: 'visible' }}>
            <defs>
              <marker
                id="arrowhead"
                markerWidth="10"
                markerHeight="7"
                refX="9"
                refY="3.5"
                orient="auto"
              >
                <polygon points="0 0, 10 3.5, 0 7" fill="#6b7280" />
              </marker>
            </defs>
            {Array.from(connections.values()).map((conn) => {
              const fromNode = nodes.get(conn.fromNodeId)
              const toNode = nodes.get(conn.toNodeId)
              if (!fromNode || !toNode) return null

              const fromX = fromNode.x + fromNode.width / 2
              const fromY = fromNode.y + fromNode.height / 2
              const toX = toNode.x + toNode.width / 2
              const toY = toNode.y + toNode.height / 2

              return (
                <line
                  key={conn.id}
                  x1={fromX}
                  y1={fromY}
                  x2={toX}
                  y2={toY}
                  stroke={conn.color}
                  strokeWidth={conn.width}
                  strokeDasharray={conn.style === 'dashed' ? '5,5' : conn.style === 'dotted' ? '2,2' : undefined}
                  markerEnd={conn.arrowType === 'end' || conn.arrowType === 'both' ? 'url(#arrowhead)' : undefined}
                />
              )
            })}
          </svg>

          {/* Render groups */}
          {Array.from(groups.values()).map((group) => (
            <div
              key={group.id}
              className="absolute border-2 rounded-lg"
              style={{
                left: group.x,
                top: group.y,
                width: group.width,
                height: group.height,
                borderColor: group.borderColor,
                backgroundColor: group.backgroundColor,
                borderRadius: group.borderRadius,
              }}
            >
              <div className="absolute -top-6 left-0 px-2 py-1 text-xs font-medium" style={{ color: group.borderColor }}>
                {group.name}
              </div>
            </div>
          ))}

          {/* Render nodes */}
          {Array.from(nodes.values()).map((node) => (
            <NodeItem
              key={node.id}
              node={node}
              isSelected={selectedIds.includes(node.id)}
              zoom={zoom}
            />
          ))}
        </div>
      </div>

      {/* Zoom Controls */}
      <ZoomControls />

      {/* Node Style Panel */}
      <NodeStylePanel />
    </div>
  )
}
